patches.new_code:
public async Task<string> FetchResource(string url)
{
    if (!Uri.TryCreate(url, UriKind.Absolute, out var uri))
        throw new ArgumentException("Invalid URL");
    if (uri.Scheme != Uri.UriSchemeHttps)
        throw new ArgumentException("Only HTTPS URLs are allowed");
    // Optional: resolve DNS and ensure the IP is not private/internal
    var host = uri.Host;
    var addresses = await Dns.GetHostAddressesAsync(host);
    if (addresses.Any(ip => ip.IsPrivate() || ip.IsLoopback || ip.IsLinkLocal))
        throw new ArgumentException("Private/internal hosts are not allowed");
    HttpResponseMessage response = await client.GetAsync(uri);
    return await response.Content.ReadAsStringAsync();
}

